
import { create } from 'zustand'

export const useUserStore = create((set, get) => ({
  // Initial state
  user: null,
  // Actions (functions to change state)
  clearUser: () => set({ user: null }),
  setUser: (userObj) => {
    clearUser()
    set({ user: userObj })
  },
  // Function to get user data
  getUser: () => get().user,
  // Function to clear user data
}))
